// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { escapeStep } from "../../../main/frontend/graph-explorer/graph-dismissal.ts";
import { contextMenuScope, selectionModifier, selectionToEdit } from "../../../main/frontend/graph-explorer/graph-selection.ts";
import { removeGraphNodes } from "../../../main/frontend/graph-explorer/graph-operations.ts";
import { canvasGraph, RDF_TYPE } from "../../../main/frontend/graph-explorer/graph-canvas-scope.ts";
import { CanvasGraph } from "../../../main/frontend/graph-explorer/graph-canvas-controller.ts";
import { nodeInDirection } from "../../../main/frontend/graph-explorer/graph-keyboard.ts";
import { toggleTypeInSelection } from "../../../main/frontend/graph-explorer/graph-facets.ts";

test("Escape closes the topmost layer: a menu, then the card and its highlight, then the selection", () => {
  assert.equal(escapeStep({ menu: true, card: true, selection: true }), "menu");
  assert.equal(escapeStep({ menu: false, card: true, selection: true }), "card");
  assert.equal(escapeStep({ menu: false, card: false, selection: true }), "selection");
  assert.equal(escapeStep({ menu: false, card: false, selection: false }), "none");
});

test("the node menu acts on the right-clicked node unless it is part of the selection", () => {
  assert.deepEqual(contextMenuScope("c", new Set(["a", "b"])), ["c"]);
  assert.deepEqual(contextMenuScope("b", new Set(["c", "a", "b"])), ["b", "a", "c"]);
  assert.deepEqual(contextMenuScope("a", new Set()), ["a"]);
});

test("a selection gesture while a filter is active starts from what the filter selects", () => {
  const matches = new Set(["a", "b"]);
  const manual = new Set(["x"]);
  assert.equal(selectionToEdit(true, matches, manual), matches);
  assert.equal(selectionToEdit(false, matches, manual), manual);
});

test("Shift and ⌘ add to the selection everywhere; Ctrl only where a Ctrl-click is not the context-menu click", () => {
  const press = (keys) => ({ shiftKey: keys.includes("shift"), metaKey: keys.includes("meta"), ctrlKey: keys.includes("ctrl") });
  assert.equal(selectionModifier(press(["shift"]), true), true);
  assert.equal(selectionModifier(press(["meta"]), true), true);
  assert.equal(selectionModifier(press(["ctrl"]), true), false);
  assert.equal(selectionModifier(press(["ctrl"]), false), true);
  assert.equal(selectionModifier(press([]), false), false);
});

const node = (id, extra = {}) => ({ id, kind: "iri", label: id.replace("urn:", ""), x: 0, y: 0, ...extra });
const edge = (source, predicate, target) => ({ id: `${source} ${predicate} ${target}`, source, predicate, target, label: predicate });

test("hiding every instance of a class does not leave the class drawn on its own", () => {
  const graph = {
    nodes: [node("urn:alice"), node("urn:bob"), node("urn:Person"), node("urn:acme")],
    edges: [
      edge("urn:alice", RDF_TYPE, "urn:Person"),
      edge("urn:bob", RDF_TYPE, "urn:Person"),
      edge("urn:alice", "urn:knows", "urn:bob"),
      edge("urn:alice", "urn:worksFor", "urn:acme"),
    ],
    revision: 1,
  };
  assert.deepEqual(canvasGraph(graph, false).nodes.map((n) => n.id), ["urn:alice", "urn:bob", "urn:acme"]);
  const remaining = removeGraphNodes(graph, new Set(["urn:alice", "urn:bob"]));
  assert.deepEqual(remaining.nodes.map((n) => n.id), ["urn:acme"]);
  assert.deepEqual(canvasGraph(remaining, false).nodes.map((n) => n.id), ["urn:acme"]);
});

test("hiding some instances keeps the class, and a class with links of its own stays", () => {
  const graph = {
    nodes: [node("urn:alice"), node("urn:bob"), node("urn:Person"), node("urn:Agent")],
    edges: [
      edge("urn:alice", RDF_TYPE, "urn:Person"),
      edge("urn:bob", RDF_TYPE, "urn:Person"),
      edge("urn:alice", RDF_TYPE, "urn:Agent"),
      edge("urn:Agent", "urn:seeAlso", "urn:bob"),
    ],
    revision: 1,
  };
  assert.deepEqual(removeGraphNodes(graph, new Set(["urn:alice"])).nodes.map((n) => n.id), ["urn:bob", "urn:Person", "urn:Agent"]);
});

test("a click on a node's label in the large renderer selects the node; screenPoint finds the node", () => {
  const frames = [];
  globalThis.requestAnimationFrame = (callback) => frames.push(callback);
  globalThis.cancelAnimationFrame = () => {};
  globalThis.window = { devicePixelRatio: 1, matchMedia: () => ({ matches: false }) };
  globalThis.ResizeObserver = class {
    constructor(callback) {
      this.callback = callback;
    }
    observe() {
      this.callback();
    }
    disconnect() {}
  };
  const noop = () => {};
  const context = new Proxy(
    { measureText: (text) => ({ width: text.length * 7 }) },
    { get: (target, key) => (key in target ? target[key] : noop), set: () => true },
  );
  const canvas = { width: 0, height: 0, getContext: () => null, addEventListener: noop, removeEventListener: noop };
  const overlay = {
    ...canvas,
    addEventListener: noop,
    dataset: {},
    style: {},
    getBoundingClientRect: () => ({ left: 0, top: 0, width: 1280, height: 780 }),
    getContext: () => context,
  };
  const selections = [];
  const props = {
    graph: {
      nodes: [
        { id: "urn:a", kind: "iri", label: "Alice in Wonderland", x: 300, y: 200 },
        { id: "urn:b", kind: "iri", label: "B", x: 700, y: 200 },
      ],
      edges: [],
      revision: 1,
    },
    transform: { x: 0, y: 0, k: 1 },
    selected: new Set(),
    focused: null,
    showLabels: false,
    groups: [],
    onTransform: noop,
    onPositions: noop,
    onInterrupt: noop,
    onSelect: (id, multiple) => selections.push([id, multiple]),
    onMenu: noop,
    onDragStart: noop,
    onBoxSelect: noop,
  };
  const view = new CanvasGraph(canvas, overlay, () => props);
  while (frames.length) frames.shift()(performance.now());
  const point = view.screenPoint("urn:a");
  assert.ok(point, "the node has a screen position");
  assert.equal(view.screenPoint("urn:missing"), null);
  // The label is drawn 16 px below the dot; its right half is well outside the dot's 12 px hit radius.
  const mouse = (x, y) => ({ pointerId: 1, pointerType: "mouse", button: 0, x, y });
  view.downAt(mouse(point.x + 50, point.y + 16));
  view.upAt(mouse(point.x + 50, point.y + 16));
  assert.deepEqual(selections, [["urn:a", false]]);
  // Empty canvas far from any dot or label is still the background.
  view.downAt(mouse(point.x, point.y + 120));
  view.upAt(mouse(point.x, point.y + 120));
  assert.deepEqual(selections.at(-1), [null, false]);
  view.dispose();
});

test("an arrow key moves to the nearest node in its direction, preferring nodes in line over ones off to the side", () => {
  const nodes = [
    { id: "centre", x: 0, y: 0 },
    { id: "right-near-diagonal", x: 120, y: 110 },
    { id: "right-in-line", x: 200, y: 10 },
    { id: "left", x: -150, y: -20 },
    { id: "up", x: 15, y: -90 },
    { id: "down-far", x: -10, y: 400 },
  ];
  assert.equal(nodeInDirection(nodes, "centre", "right"), "right-in-line");
  assert.equal(nodeInDirection(nodes, "centre", "left"), "left");
  assert.equal(nodeInDirection(nodes, "centre", "up"), "up");
  assert.equal(nodeInDirection(nodes, "centre", "down"), "right-near-diagonal");
  assert.equal(nodeInDirection(nodes, "left", "left"), null);
  assert.equal(nodeInDirection(nodes, "missing", "left"), null);
});

test("a legend chip adds its type to the type filter or takes it out, and leaves the other filters alone", () => {
  const empty = new Map();
  const person = toggleTypeInSelection(empty, "type", "Person");
  assert.deepEqual([...person.get("type")], ["Person"]);
  const both = toggleTypeInSelection(new Map([...person, ["age", new Set(["39"])]]), "type", "City");
  assert.deepEqual([...both.get("type")].sort(), ["City", "Person"]);
  assert.deepEqual([...both.get("age")], ["39"]);
  const city = toggleTypeInSelection(both, "type", "Person");
  assert.deepEqual([...city.get("type")], ["City"]);
  const none = toggleTypeInSelection(new Map([["type", new Set(["City"])]]), "type", "City");
  assert.equal(none.has("type"), false);
});

test("the large renderer names the node nearest the middle of the view, where arrow keys start", () => {
  const frames = [];
  globalThis.requestAnimationFrame = (callback) => frames.push(callback);
  globalThis.cancelAnimationFrame = () => {};
  globalThis.window = { devicePixelRatio: 1, matchMedia: () => ({ matches: false }) };
  globalThis.ResizeObserver = class {
    constructor(callback) {
      this.callback = callback;
    }
    observe() {
      this.callback();
    }
    disconnect() {}
  };
  const noop = () => {};
  const canvas = { width: 0, height: 0, getContext: () => null, addEventListener: noop, removeEventListener: noop };
  const overlay = { ...canvas, dataset: {}, style: {}, getBoundingClientRect: () => ({ left: 0, top: 0, width: 1280, height: 780 }) };
  const props = {
    graph: {
      nodes: [
        { id: "urn:edge", kind: "iri", label: "Edge", x: 40, y: 40 },
        { id: "urn:middle", kind: "iri", label: "Middle", x: 610, y: 420 },
      ],
      edges: [],
      revision: 1,
    },
    transform: { x: 0, y: 0, k: 1 },
    selected: new Set(),
    focused: null,
    showLabels: false,
    groups: [],
    onTransform: noop, onPositions: noop, onInterrupt: noop, onSelect: noop, onMenu: noop, onDragStart: noop, onBoxSelect: noop,
  };
  const view = new CanvasGraph(canvas, overlay, () => props);
  assert.equal(view.centreNode(), "urn:middle");
  view.dispose();
});
